<?php require_role('buyer');$id=safe_int($_GET['id']??0);$buyerId=(int)user()['buyer_id'];$self=base_path('comprador/pedido-detalhes.php?id='.$id);
$load=function()use($id,$buyerId){$s=db()->prepare('SELECT * FROM orders WHERE id=? AND buyer_id=?');$s->execute([$id,$buyerId]);return $s->fetch();};$o=$load();if(!$o)redirect(base_path('comprador/pedidos.php'));
$cancellable=fn(array $items)=>(bool)array_filter($items,fn($i)=>$i['status']!=='cancelled')&&!array_filter($items,fn($i)=>!in_array($i['status'],['pending','confirmed','cancelled'],true));
if(is_post()&&($_POST['action']??'')==='cancel'){verify_csrf($_POST['csrf']??'');$reason=trim((string)($_POST['reason']??''));$reason=mb_substr($reason!==''?$reason:'Cancelado pelo comprador',0,255);$pdo=db();
  try{$pdo->beginTransaction();$s=$pdo->prepare('SELECT id,order_number FROM orders WHERE id=? AND buyer_id=? FOR UPDATE');$s->execute([$id,$buyerId]);$locked=$s->fetch();if(!$locked)throw new RuntimeException('Pedido não encontrado.');
    $s=$pdo->prepare('SELECT id,product_id,farmer_id,quantity,status FROM order_items WHERE order_id=? FOR UPDATE');$s->execute([$id]);$all=$s->fetchAll();if(!$cancellable($all))throw new RuntimeException('Este pedido já não pode ser cancelado: há itens em preparação ou enviados.');
    $toCancel=array_values(array_filter($all,fn($i)=>$i['status']!=='cancelled'));$pdo->prepare('UPDATE order_items SET status="cancelled" WHERE order_id=? AND status<>"cancelled"')->execute([$id]);restore_item_stock($pdo,$toCancel,'Cancelamento do pedido '.$locked['order_number'].' pelo comprador');
    $pdo->prepare('UPDATE orders SET cancel_reason=? WHERE id=?')->execute([$reason,$id]);$payBefore=order_payment_locked($pdo,$id);$new=recalc_order_status($pdo,$id);
    // Pagamento já pago: fica um pedido de reembolso para o admin processar.
    $refundId=($payBefore&&$payBefore['status']==='paid')?create_refund_for_cancel($pdo,$id,cancel_refund_amount($pdo,$id,$new,array_column($toCancel,'id')),'Cancelamento pelo comprador: '.$reason):null;
    $fs=$pdo->prepare('SELECT DISTINCT f.user_id FROM order_items oi JOIN farmers f ON f.id=oi.farmer_id WHERE oi.order_id=?');$fs->execute([$id]);foreach($fs->fetchAll(PDO::FETCH_COLUMN) as $fu)notify((int)$fu,'Pedido cancelado','O comprador cancelou o pedido '.$locked['order_number'].'. Motivo: '.$reason);
    audit(current_user_id(),'cancel','orders','Comprador cancelou o pedido '.$locked['order_number']);$pdo->commit();flash('success','Pedido cancelado.'.($refundId?' Foi registado um pedido de reembolso que será processado pela administração.':''));}
  catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();if(!$e instanceof RuntimeException)error_log('cancelar pedido: '.$e->getMessage());flash('danger',$e instanceof RuntimeException?$e->getMessage():'Não foi possível cancelar o pedido.');}
  redirect($self);}
$s=db()->prepare('SELECT oi.*,p.main_image FROM order_items oi LEFT JOIN products p ON p.id=oi.product_id WHERE oi.order_id=? ORDER BY oi.id');$s->execute([$id]);$items=$s->fetchAll();
$s=db()->prepare('SELECT method,status,paid_at FROM payments WHERE order_id=? LIMIT 1');$s->execute([$id]);$pay=$s->fetch()?:null;
$s=db()->prepare('SELECT product_id,rating FROM reviews WHERE user_id=? AND order_id=?');$s->execute([user()['id'],$id]);$reviewed=$s->fetchAll(PDO::FETCH_KEY_PAIR);
$s=db()->prepare('SELECT * FROM refunds WHERE order_id=? ORDER BY id');$s->execute([$id]);$refunds=$s->fetchAll();$couponCode=null;if($o['coupon_id']){$s=db()->prepare('SELECT code FROM coupons WHERE id=?');$s->execute([$o['coupon_id']]);$couponCode=$s->fetchColumn()?:null;}
