$statuses=['pending','confirmed','preparing','ready','shipping','delivered'];$progress=array_search($o['status'],$statuses,true);$canCancel=$cancellable($items);
include __DIR__.'/../includes/header.php';?><div class="dashboard-layout"><?php include __DIR__.'/../includes/sidebar.php';?><section class="dashboard-content"><div class="dashboard-top"><div><span class="eyebrow">Pedido <?=e($o['order_number'])?></span><h1>Acompanhar pedido</h1><p class="text-muted small mb-0">Feito em <?=date('d/m/Y H:i',strtotime($o['created_at']))?><?php if($o['invoice_number']): ?> · Fatura <?=e($o['invoice_number'])?><?php endif; ?></p></div><div class="d-flex flex-wrap gap-2 align-items-center"><?=order_status_badge($o['status'])?><a class="btn btn-sm btn-outline-primary" href="<?=base_path('recibo.php?id='.$id)?>" target="_blank" rel="noopener"><i class="bi bi-printer me-1"></i>Recibo</a><a class="btn btn-sm btn-outline-secondary" href="<?=base_path('denunciar.php?pedido='.$id)?>"><i class="bi bi-flag me-1"></i>Comunicar problema</a></div></div>
<?php if($o['status']==='cancelled'): ?><div class="alert alert-danger"><i class="bi bi-x-circle me-2"></i><strong>Pedido cancelado.</strong><?php if(!empty($o['cancel_reason'])): ?> Motivo: <?=e($o['cancel_reason'])?><?php endif; ?></div><?php else: ?><div class="order-timeline"><?php foreach($statuses as $idx=>$st):$done=$progress!==false&&$progress>=$idx;?><div class="timeline-step <?=$done?'done':''?>"><span><?=$done?'<i class="bi bi-check-lg" aria-hidden="true"></i>':$idx+1?></span><small><?=e(order_status_label($st))?></small></div><?php endforeach;?></div><?php endif; ?>
<div class="row g-4 mt-2"><div class="col-lg-8"><div class="content-card"><h4>Produtos</h4><?php foreach($items as $i):$canReview=($i['status']==='delivered'||$o['status']==='delivered')&&$i['status']!=='cancelled';?><div class="order-item flex-wrap"><div class="cart-product"><img src="<?=e(get_product_image($i['main_image']))?>" alt="<?=e($i['product_name'])?>"><div><strong><?=e($i['product_name'])?></strong><small><?=e($i['quantity'])?> <?=e($i['unit'])?> × <?=money($i['unit_price'])?></small><div class="mt-1"><?=order_status_badge($i['status'])?></div></div></div><strong><?=money($i['subtotal'])?></strong>
<?php if($canReview): ?><div class="w-100 mt-2"><?php if(isset($reviewed[$i['product_id']])): ?><span class="small text-success"><i class="bi bi-star-fill me-1"></i>Avaliou com <?=safe_int($reviewed[$i['product_id']])?>/5</span><?php else: ?><form class="review-form row g-2 align-items-end" data-review-form><input type="hidden" name="order_id" value="<?=$id?>"><input type="hidden" name="product_id" value="<?=safe_int($i['product_id'])?>"><div class="col-sm-3"><label class="form-label small mb-0" for="rt-<?=safe_int($i['id'])?>">Nota</label><select id="rt-<?=safe_int($i['id'])?>" name="rating" class="form-select form-select-sm" required><option value="">—</option><?php for($r=5;$r>=1;$r--): ?><option value="<?=$r?>"><?=$r?> <?=$r===1?'estrela':'estrelas'?></option><?php endfor; ?></select></div><div class="col-sm-6"><label class="form-label small mb-0" for="cm-<?=safe_int($i['id'])?>">Comentário</label><input id="cm-<?=safe_int($i['id'])?>" name="comment" class="form-control form-control-sm" maxlength="1000" placeholder="Opcional"></div><div class="col-sm-3"><button class="btn btn-sm btn-primary w-100"><i class="bi bi-star me-1"></i>Avaliar</button></div></form><?php endif; ?></div><?php endif; ?></div><?php endforeach;?></div>
<div class="content-card mt-4" id="mensagens"><h4>Mensagens com o agricultor</h4><p class="small text-muted">Fale diretamente com cada agricultor sobre este pedido.</p><?php foreach($orderFarmers as $fid=>$fname): ?><?=order_thread_html($threads[$fid],$id,(int)$fid,(int)user()['id'],'Conversa com '.$fname)?><?php endforeach; ?></div></div>
<div class="col-lg-4"><div class="summary-card"><h4>Entrega</h4><p class="small text-muted mb-1"><?=e($o['delivery_name'])?></p><p class="small text-muted mb-1"><?=e($o['delivery_phone'])?></p><p class="small text-muted"><?=e($o['address'])?>, <?=e($o['district'])?>, <?=e($o['city'])?>, <?=e($o['province'])?></p><?php if($o['delivery_eta_days']!==null): ?><p class="small mb-1"><i class="bi bi-truck me-1"></i>Prazo estimado: <?=safe_int($o['delivery_eta_days'])?> dia(s)</p><?php endif; ?><hr><h4>Pagamento</h4><div class="summary-line"><span>Método</span><strong><?=e(payment_method_label((string)($pay['method']??'')))?></strong></div><div class="summary-line"><span>Estado</span><strong><?=e(payment_status_label((string)($pay['status']??$o['payment_status'])))?></strong></div><hr><div class="summary-line"><span>Subtotal</span><strong><?=money($o['subtotal'])?></strong></div><?php if((float)$o['discount']>0): ?><div class="summary-line text-success"><span>Desconto<?=$couponCode?' <small>'.e($couponCode).'</small>':''?></span><strong>−<?=money($o['discount'])?></strong></div><?php endif; ?><div class="summary-line"><span>Entrega</span><strong><?=(float)$o['delivery_fee']>0?money($o['delivery_fee']):'A combinar'?></strong></div><div class="summary-line total"><span>Total</span><strong><?=money($o['total'])?></strong></div><?php if($refunds): ?><hr><h4>Reembolsos</h4><?php foreach($refunds as $rf): ?><div class="summary-line"><span><?=date('d/m/Y',strtotime($rf['created_at']))?> <span class="badge text-bg-<?=e(refund_status_class($rf['status']))?>"><?=e(refund_status_label($rf['status']))?></span></span><strong><?=money($rf['amount'])?></strong></div><?php endforeach; ?><?php endif; ?>
