<script>
document.querySelectorAll('[data-review-form]').forEach(function(f){f.addEventListener('submit',async function(ev){ev.preventDefault();var btn=f.querySelector('button');btn.disabled=true;var fd=new FormData(f),payload={csrf:window.CSRF};fd.forEach(function(v,k){payload[k]=v;});
  try{var r=await fetch(window.BASE_URL+'/api/avaliacoes.php',{method:'POST',headers:{'Content-Type':'application/json','X-Requested-With':'XMLHttpRequest'},body:JSON.stringify(payload)});var d={};try{d=await r.json();}catch(e){}if(!r.ok||!d.success)throw new Error(d.message||'Ocorreu um erro.');alert(d.message);location.reload();}
  catch(e){alert(e.message);btn.disabled=false;}});});
